	('9bc65c12-ddc4-47b6-a46f-5536eb97f086',2,1885,'WAH BASIC - Lake Arrowhead, CA, US | Robert Buzbee',NULL,'weekly','27555 North Bay Rd','CA',NULL,'Lake Arrowhead','92352','US',-117.2029590,34.2669030,'California',NULL,NULL,NULL,NULL,0,0,'2024-04-10 15:21:45',0,'men','2021-10-21 15:21:45','2021-10-24 15:21:45',NULL,'Space is limited to 12 men.',16597,367941,'\"{\\\"lid\\\":\\\"6328\\\",\\\"name\\\":\\\"\\\",\\\"street\\\":\\\"27555 North Bay Rd\\\",\\\"additional\\\":\\\"\\\",\\\"city\\\":\\\"Lake Arrowhead\\\",\\\"province\\\":\\\"CA\\\",\\\"postal_code\\\":\\\"92352\\\",\\\"country\\\":\\\"us\\\",\\\"latitude\\\":\\\"34.266903\\\",\\\"longitude\\\":\\\"-117.202959\\\",\\\"source\\\":\\\"3\\\",\\\"is_primary\\\":\\\"0\\\",\\\"province_name\\\":\\\"California\\\",\\\"country_name\\\":\\\"United States\\\"}\"','/wah-basic-lake-arrowhead-ca-us-robert-buzbee-0',NULL,'2021-09-25 01:09:27','2024-04-10 15:21:45');
